{
  "description": "The creature is shown in right-facing side profile standing on a small patch of dirt with pebbles and sparse green tufts. It has a stout, elongated body with a pale pink, heavily wrinkled ventral surface and four short thick limbs, and a dorsal covering of large overlapping glossy brown scales that extends from the back of the neck along the arched back and down the entire length of a long tapering tail. The head is broad, rounded and pale pink with large prominent eyes, a blunt snout and a slight smile, and six feathery pink external gills protrude from the sides of the neck behind the head. The overall appearance combines a soft-skinned amphibian underside and head with an armored scaly back and tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, rounded and blunt-snouted, pale pink with soft wrinkled skin, large bulging eyes with black pupils and light blue irises, small pink nostrils, a slightly upturned closed mouth, and scattered dark brown speckles on the dorsal surface",
      "where": "at the front right end of the body"
    },
    {
      "part": "gills",
      "looks_like": "six feathery pink external gills with a central stalk and many fine filamentous branches, three on each side of the neck, pink with darker red frills",
      "where": "protruding outward and slightly backward from the sides of the neck immediately behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, fleshy limbs with pale pink wrinkled skin and visible folds at the joints",
      "where": "two forelimbs under the chest and two hindlimbs under the rear body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "splayed feet with five slender digits each tipped with a small dark claw, pale pink with wrinkled skin",
      "where": "at the ends of each of the four legs, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and tapering to a rounded tip, dorsally covered in overlapping brown scales and ventrally showing pale pink wrinkled skin with transverse folds",
      "where": "extending to the left from the rear of the body"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, glossy keratinous scales in shades of brown with darker brown edges and lighter tan centers, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from the back of the neck over the back and down the top and sides of the tail"
    },
    {
      "part": "markings",
      "looks_like": "small dark brown to black speckles on the top of the head and snout, and transverse wrinkled ridges encircling the belly and limbs",
      "where": "speckles on the dorsal head, wrinkles on the pale pink belly, throat, and limbs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
